// Keep links first seen inside the window, from a strong enough, non-spammy linking domain.
const s = $('Settings').first().json;
const since = Date.now() - (Number(s.lookbackDays) || 7) * 86400000;
const minRank = Number(s.minDomainRank) || 0;
const maxSpam = s.maxSpamScore === '' || s.maxSpamScore == null ? 100 : Number(s.maxSpamScore);
const own = String(s.yourDomain).trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');
const date = new Date().toISOString().slice(0, 10);
const out = [];
for (const { json: l } of $input.all()) {
  if (l.found === false || !l.firstSeen) continue;
  if (Date.parse(l.firstSeen) < since) continue;
  if ((l.sourceDomainRank ?? 0) < minRank) continue;
  if ((l.spamScore ?? 0) > maxSpam) continue;
  const target = String(l.target || '').toLowerCase().replace(/^www\./, '');
  out.push({ json: {
    date, whose: target === own ? 'yours' : 'competitor', target: l.target,
    linkingDomain: l.sourceDomain, linkingPage: l.sourceUrl, pageTitle: l.sourceTitle ?? null,
    anchor: l.anchor ?? null, dofollow: l.dofollow, domainRank: l.sourceDomainRank ?? null,
    spamScore: l.spamScore ?? null, firstSeen: String(l.firstSeen).slice(0, 10), linksTo: l.targetUrl,
  } });
}
return out;

// One Slack message for the week; nothing is sent when there is no new link.
const links = $input.all().map((i) => i.json).sort((a, b) => (b.domainRank ?? 0) - (a.domainRank ?? 0));
if (!links.length) return [];
const line = (l) => `• <${l.linkingPage}|${l.linkingDomain}> (rank ${l.domainRank ?? '?'}${l.dofollow ? '' : ', nofollow'}) → ${l.linksTo}${l.anchor ? ` _"${String(l.anchor).slice(0, 60)}"_` : ''}`;
const mine = links.filter((l) => l.whose === 'yours');
const theirs = links.filter((l) => l.whose === 'competitor');
const parts = [`:link: *New backlinks this week*: ${mine.length} to you, ${theirs.length} to competitors`];
if (mine.length) parts.push(`*Yours*\n${mine.slice(0, 15).map(line).join('\n')}`);
if (theirs.length) parts.push(`*Competitors (outreach ideas)*\n${theirs.slice(0, 15).map((l) => `${line(l)} [${l.target}]`).join('\n')}`);
parts.push('Full list in the Backlinks sheet.');
return [{ json: { text: parts.join('\n\n') } }];
